// 1. Canonical Schema Validation
const lead = $input.first().json;

const requiredFields = ['lead_id', 'source', 'contact', 'message', 'received_at'];
const missing = requiredFields.filter(f => lead[f] === undefined || lead[f] === null);

if (missing.length > 0) {
  throw new Error(`SchemaValidationError: Missing required fields: ${missing.join(', ')}`);
}

if (!lead.contact || (!lead.contact.email && !lead.contact.phone)) {
  // Incomplete contact, tag for downstream review
  lead._schema_warning = 'Incomplete contact details';
}

return [{ json: lead }];

