// Deterministic Rule Engine
const lead = $('Validate Canonical Schema').first().json;
const aiResponse = $input.first().json;

let analysis;
try {
  if (aiResponse.choices && aiResponse.choices[0]) {
    analysis = JSON.parse(aiResponse.choices[0].message.content);
  } else {
    throw new Error('AI response fallback');
  }
} catch (err) {
  // Graceful degradation heuristic
  const msg = (lead.message || '').toLowerCase();
  analysis = {
    industry: msg.includes('restaurant') ? 'restaurant' : null,
    service_requested: msg.includes('line') ? 'LINE AI customer service' : 'automation',
    problem: lead.message,
    budget: { amount: null, currency: 'THB', stated: false },
    timeline_days: 30,
    intent: 'medium',
    language: 'en',
    summary: 'Fallback extraction due to AI timeout/error',
    missing_information: ['ai_parsing_verification'],
    confidence_score: 0.50
  };
}

// 1. Service Fit (0-25)
let s_fit = 0;
const s_req = (analysis.service_requested || '').toLowerCase();
const prob = (analysis.problem || '').toLowerCase();
const combined = `${s_req} ${prob}`;

if (combined.includes('hardware') || combined.includes('seo') || combined.includes('backlink')) {
  s_fit = 0;
} else if (combined.includes('line ai') || combined.includes('crm') || combined.includes('reminder') || combined.includes('bot')) {
  s_fit = 25;
} else if (combined.includes('shopify') || combined.includes('integration') || combined.includes('sheet')) {
  s_fit = 15;
} else {
  s_fit = 5;
}

// 2. Intent (0-20)
let p_intent = 0;
if (analysis.intent === 'high') p_intent = 20;
else if (analysis.intent === 'medium') p_intent = 10;

// 3. Urgency (0-20)
let urg = 5;
if (analysis.timeline_days && analysis.timeline_days <= 30) urg = 20;
else if (analysis.timeline_days && analysis.timeline_days <= 90) urg = 12;

// 4. Budget Fit (0-20)
let b_fit = 10;
let b_thb = 0;
if (analysis.budget && analysis.budget.stated && analysis.budget.amount) {
  b_thb = analysis.budget.currency === 'USD' ? analysis.budget.amount * 35 : analysis.budget.amount;
  if (b_thb >= 100000) b_fit = 20;
  else if (b_thb >= 40000) b_fit = 15;
  else b_fit = 5;
}

// 5. Decision Authority (0-5)
const name = (lead.contact?.name || '').toLowerCase();
const isExec = /\b(dr|ceo|founder|director|owner|vp|manager)\b/.test(name);
const d_auth = isExec ? 5 : 0;

// 6. Company Fit (0-5)
const c_fit = (analysis.industry || lead.company?.size) ? 5 : 0;

// 7. Data Completeness (0-5)
const d_comp = (lead.contact?.email && lead.contact?.phone && lead.company?.name) ? 5 : 3;

let total = s_fit + p_intent + urg + b_fit + d_auth + c_fit + d_comp;
if (analysis.intent === 'spam') total = 0;
total = Math.max(0, Math.min(100, total));

let priority = 'disqualified';
if (analysis.intent !== 'spam') {
  if (total >= 75) priority = 'high';
  else if (total >= 45) priority = 'medium';
  else if (total >= 20) priority = 'low';
}

// Human Review Triggers
const reviewReasons = [];
if (analysis.confidence_score < 0.65) reviewReasons.push('Low AI confidence threshold');
if (b_thb >= 300000) reviewReasons.push('Enterprise budget opportunity (>= 300k THB)');
if (s_fit === 0 && analysis.intent !== 'spam') reviewReasons.push('Unsupported service inquiry');
if (analysis.intent === 'spam') reviewReasons.push('Spam solicitation suppressed');
if (analysis.intent === 'ambiguous') reviewReasons.push('Ambiguous lead triage');

return [{
  json: {
    lead: lead,
    analysis: analysis,
    score_result: {
      lead_id: lead.lead_id,
      total_score: total,
      priority: priority,
      score_breakdown: {
        service_fit: s_fit,
        purchase_intent: p_intent,
        urgency: urg,
        budget_fit: b_fit,
        decision_authority: d_auth,
        company_fit: c_fit,
        data_completeness: d_comp
      },
      requires_human_review: reviewReasons.length > 0,
      human_review_reasons: reviewReasons,
      scored_at: new Date().toISOString()
    }
  }
}];

